 function arrange(){const incoming=new Set(map.choices.map(c=>String(c.targetBranchingNodeId))),visited=new Set(),levels={},positions={};const queue=map.nodes.filter(n=>!incoming.has(String(n.branchingNodeId))).map(n=>[n.branchingNodeId,0]);if(!queue.length&&map.nodes.length)queue.push([map.nodes[0].branchingNodeId,0]);while(queue.length){const [id,depth]=queue.shift();if(visited.has(String(id)))continue;visited.add(String(id));positions[id]={positionX:50+depth*300,positionY:70+(levels[depth]||0)*240};levels[depth]=(levels[depth]||0)+1;for(const c of map.choices.filter(c=>String(c.sourceBranchingNodeId)===String(id)))queue.push([c.targetBranchingNodeId,depth+1]);}for(const n of map.nodes)if(!positions[n.branchingNodeId]){const row=levels[0]||0;positions[n.branchingNodeId]={positionX:50,positionY:70+row*240};levels[0]=row+1;}setMap(m=>({...m,nodes:m.nodes.map(n=>({...n,...positions[n.branchingNodeId]}))}));setLayoutDraft(true)}

