 {inspecting&&<Drawer lang={lang} title={inspecting.choice?word(lang,'تفاصيل الاختيار','Choice details'):word(lang,'تفاصيل إضافية','More details')} onClose={()=>setInspecting(null)}><NarrativeInspector project={project} {...inspecting} nodes={map.nodes} variables={variables} lang={lang} onSaved={refresh}/></Drawer>}
