const STAT_KEYS=['attack','defense','speed','rangeStat','stamina','special'];
const STAT_NAMES={attack:['الهجوم','Attack'],defense:['الدفاع','Defense'],speed:['السرعة','Speed'],rangeStat:['المدى','Range'],stamina:['التحمل','Stamina'],special:['مهارة خاصة','Special']};
export function GameBalance({project,lang}){
 const [toolReady,setToolReady]=useState(!API_MODE||project.diagrams?.some(d=>d.outputType==='STORY_MAP')),[details,setDetails]=useState({}),[storyProfiles,setStoryProfiles]=useState([]),[profileError,setProfileError]=useState('');
 const [fighters,setFighters]=useState([]),[drawer,setDrawer]=useState(null),[edit,setEdit]=useState(null),[profile,setProfile]=useState(''),[name,setName]=useState(''),[role,setRole]=useState(''),[stats,setStats]=useState(defaultStats),[report,setReport]=useState(null),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const profiles=API_MODE?storyProfiles:(project.elements||[]).filter(e=>e.type==='characters'&&e.name);
 useEffect(()=>{if(!toolReady)return;let active=true;store.storyProfiles(project).then(rows=>{if(active){setStoryProfiles(rows);setProfileError('')}}).catch(e=>{if(active)setProfileError(e.message)});return()=>{active=false}},[toolReady,project.id,project.activeOutputId]);
 const refresh=useCallback(async()=>{
  const [gameplay,originals]=await Promise.all([store.fighters(project),store.storyProfiles(project)]);
  setFighters(gameplay);setStoryProfiles(originals);
 },[project]);useEffect(()=>{if(toolReady)refresh().catch(e=>setError(e.message))},[refresh,toolReady]);
 async function commit(action){setBusy(true);setError('');try{await action();await refresh();setDrawer(null);setEdit(null);return true}catch(e){setError(e.message);return false}finally{setBusy(false)}}
 function formOpen(f){setEdit(f||null);setName(f?.name||'');setRole(f?.role||'');setProfile(f?.characterProfileId?String(f.characterProfileId):'');setStats(Object.fromEntries(STAT_KEYS.map(k=>[k,f?.[k]??null])));setDetails(Object.fromEntries(['weaponName','weaponType','strengths','weaknesses'].map(k=>[k,f?.[k]??''])));setDrawer('character')}
 async function saveCharacter(e){e.preventDefault();const data={name:name.trim(),role:role.trim(),...details,...stats};if(!data.name)return;await commit(async()=>{if(edit){await store.updateFighter(project,edit.id??edit.characterId,data);if(profile&&String(profile)!==String(edit.characterProfileId||''))await store.linkFighter(project,edit.id??edit.characterId,Number(profile));if(!profile&&edit.characterProfileId)await store.unlinkFighter(project,edit.id??edit.characterId);return}const before=await store.fighters(project);await store.addFighter(project,data);if(profile){const after=await store.fighters(project);const old=new Set(before.map(chosenId));const created=after.find(c=>!old.has(chosenId(c)));if(!created)throw Error(word(lang,'أُنشئت الشخصية، لكن تعذر تحديد رقمها لربطها. أعيدي فتحها وحاولي الربط.','Character created but could not be linked automatically. Reopen it and link the saved profile.'));await store.linkFighter(project,created.id??created.characterId,Number(profile))}})}
 async function analyze(){setBusy(true);setError('');try{setReport(await store.analyzeFighters(project))}catch(e){setError(e.message)}finally{setBusy(false)}}
 const active=report?.analyzedCharacters??0;
 if(!toolReady)return <ToolDiagramGate lang={lang} onCreate={async()=>{await diagramIdFor(project,'STORY_MAP',true);setToolReady(true)}}/>;
 return <section className="ux-tool-page"><ToolHeader lang={lang} icon={Activity} kicker="SANA · GAME BALANCE" title={word(lang,'توازن شخصيات اللعبة','Game character balance')} subtitle={word(lang,'استخدمي شخصية محفوظة من القصة، أو أضيفي شخصية جديدة، وقارني نقاط القوة بصريًا.','Use an existing story character or add a new playable one, then compare stats visually.')} actions={<><Action icon={BarChart3} light onClick={analyze} disabled={busy||fighters.length===0}>{word(lang,'تحليل التوازن','Analyze')}</Action><Action icon={UserRound} onClick={()=>formOpen(null)}>{word(lang,'إضافة شخصية','Add character')}</Action></>}/>
 <ErrorBanner error={error} onClose={()=>setError('')}/>
 <section className="sana-story-profiles" aria-label={word(lang,'شخصيات القصة','Story characters')}>
 <h3><UserRound size={18}/>{word(lang,'شخصيات القصة الأصلية','Original story characters')} <span>{profiles.length}</span></h3>
 <p>{word(lang,'هذه الشخصيات موجودة في القصة، وتقدرين تستخدمينها في التوازن بدون ما تختفي من خريطة العلاقات.','These characters stay in the story map and can also be used in balance.')}</p>
 {profileError&&<p role="alert" className="sana-profile-error">{profileError}</p>}
 {profiles.length>0?<div className="sana-story-profile-list">{profiles.map(p=>{const attached=fighters.filter(f=>String(f.characterProfileId)===String(p.entityId||p.id));return <div key={p.entityId||p.id}><strong>{p.name}</strong><span>{attached.length?word(lang,'✓ مستخدمة في التوازن','✓ Used in balance'):word(lang,'جاهزة للاستخدام','Ready to use')}</span></div>})}</div>:<small>{word(lang,'ما ظهرت شخصيات قصصية في مخطط القصة الحالي.','No story characters found in the story diagram.')}</small>}
 </section><CharacterRadarChart fighters={fighters} lang={lang}/><div className="ux-balance-layout"><div className="ux-balance-characters">{fighters.length===0?<EmptySpace icon={Gamepad2} title={word(lang,'ما فيه شخصيات لاعبة بعد','No playable characters yet')} subtitle={word(lang,'اختاري شخصية قصصية محفوظة أو أنشئي أول شخصية لاعبة.','Link a saved story character or create a new one.')} action={<Action onClick={()=>formOpen(null)}>{word(lang,'إضافة شخصية','Add character')}</Action>}/>:<div className="ux-balance-grid">{fighters.map(f=><article className="ux-balance-card" key={chosenId(f)}><header><span className="ux-avatar"><UserRound size={24}/></span><div><strong>{f.name}</strong><small>{f.characterProfileName?`${word(lang,'من القصة:','From story:')} ${f.characterProfileName}`:(f.role||word(lang,'شخصية قابلة للعب','Playable character'))}</small></div><button className="ux-icon" onClick={()=>formOpen(f)} aria-label={word(lang,'تعديل','Edit')}><Pencil size={16}/></button></header><div className="ux-stats-rows">{STAT_KEYS.map(k=><div className="ux-stat-row" key={k}><span>{word(lang,...STAT_NAMES[k])}</span><div className="ux-stat-meter"><i style={{width:`${Math.max(0,Math.min(10,Number(f[k]??0)))*10}%`}}/></div><b>{f[k]??'—'}</b></div>)}</div><footer><span>{STAT_KEYS.every(k=>f[k]!=null)?STAT_KEYS.reduce((s,k)=>s+Number(f[k]),0):'—'} / 60 {word(lang,'نقطة','pts')}</span><button onClick={()=>{if(window.confirm(word(lang,'حذف شخصية اللعبة؟ الشخصية القصصية الأصلية ستبقى محفوظة.','Delete playable character? The original story profile will remain.')))commit(()=>store.deleteFighter(project,f.id??f.characterId))}} aria-label={word(lang,'حذف','Delete')}><Trash2 size={16}/></button></footer></article>)}</div>}</div>
 {report&&<section className="ux-report" aria-label={word(lang,'نتيجة التحليل','Analysis results')}><div className="ux-report-top"><div><small>SANA · BALANCE INSIGHT</small><h2>{word(lang,'ملخص توازن الشخصيات','Character balance summary')}</h2></div><button onClick={()=>setReport(null)} aria-label={word(lang,'إغلاق التقرير','Close report')}><X size={17}/></button></div><div className="ux-report-metrics"><div><small>{word(lang,'الشخصيات','Characters')}</small><strong>{report.totalCharacters??0}</strong></div><div><small>{word(lang,'تم تحليلها','Analyzed')}</small><strong>{active}</strong></div><div><small>{word(lang,'متوسط النقاط','Average points')}</small><strong>{report.averagePoints==null?'—':Number(report.averagePoints).toFixed(1)}</strong></div></div>{(report.characters||[]).map(r=><div className="ux-report-character" key={r.characterId}><div><strong>{r.name}</strong><span>{r.totalPoints} {word(lang,'نقطة','points')}</span></div>{r.warnings?.length?<ul>{r.warnings.map((w,i)=><li key={i}>{word(lang,'هذه الشخصية تحتاج مراجعة بسيطة مقارنة ببقية الشخصيات.','This character may need a small balance review compared with the others.')}</li>)}</ul>:<p><Check size={15}/>{word(lang,'توزيع النقاط يبدو متقاربًا ومريحًا لهذه الشخصية.','This character looks well-balanced overall.')}</p>}</div>)}{(report.notes||[]).length>0&&<div className="ux-report-notes"><Info size={17}/><div>{report.notes.map((n,i)=><p key={i}>{lang==='ar'?(n.includes('Only one')?'نحتاج شخصيتين على الأقل بإحصائيات كاملة عشان تكون المقارنة أوضح.':n.includes('without gameplay')?'بعض الشخصيات ما دخلت في المقارنة لأن بياناتها ناقصة.':n.includes('Equal total')?'حتى لو تساوت النقاط، الأفضل تجرّبين الشخصيات داخل اللعبة للتأكد من التوازن.':n.includes('No characters')?'لسه ما فيه شخصيات جاهزة للتحليل.':n):n}</p>)}</div></div>}<Hint>{word(lang,'هذا الملخص يساعدك تراجعين الأرقام بسرعة، وبعده يبقى اختبار اللعب هو الأهم.','Use this summary for a quick review, then rely on playtesting for the final call.')}</Hint></section>}
 </div>
 {drawer&&<Drawer lang={lang} onClose={()=>setDrawer(null)} title={edit?word(lang,'تعديل شخصية اللعبة','Edit playable character'):word(lang,'إضافة شخصية لاعبة','Add a playable character')} desc={word(lang,'لو عندك شخصية محفوظة، اختاريها هنا بدل كتابة الاسم من جديد.','Select a saved story character instead of retyping it.')}>
 <form className="ux-form" onSubmit={saveCharacter}><Labeled label={word(lang,'استخدمي شخصية من القصة (اختياري)','Use a saved story character (optional)')}><select value={profile} onChange={e=>{setProfile(e.target.value);const selected=profiles.find(p=>String(p.entityId||p.id)===e.target.value);if(selected&&!edit){setName(selected.name);setRole(selected.role||'')}}}><option value="">{word(lang,'شخصية جديدة بدون ربط','New character (no link)')}</option>{profiles.map(p=><option key={p.id} value={p.entityId||p.id}>{p.name}</option>)}</select></Labeled>{!profiles.length&&<Hint>{word(lang,'ما عندك شخصية قصصية بعد؟ يمكنك إنشاء شخصية هنا بدون ربط، أو إضافتها من قسم الشخصيات أولًا.','No saved story profiles yet? Create an unlinked character here or add a story character first.')}</Hint>}{edit&&edit.characterProfileId&&<Hint>{word(lang,'الشخصية مرتبطة مسبقًا بملف قصصي؛ الحذف هنا ما يحذف ذلك الملف.','Already linked to a story profile; deleting gameplay data will not delete it.')}</Hint>}
 <Labeled label={word(lang,'اسم الشخصية','Character name')}><input required maxLength={100} value={name} onChange={e=>setName(e.target.value)}/></Labeled><Labeled label={word(lang,'الدور (اختياري)','Role (optional)')}><input maxLength={100} value={role} onChange={e=>setRole(e.target.value)}/></Labeled>{['weaponName','weaponType','strengths','weaknesses'].map((k,i)=><Labeled key={k} label={word(lang,...[['اسم السلاح','Weapon name'],['نوع السلاح','Weapon type'],['نقاط القوة','Strengths'],['نقاط الضعف','Weaknesses']][i])}><textarea rows={2} value={details[k]||''} onChange={e=>setDetails({...details,[k]:e.target.value})}/></Labeled>)}<div className="ux-drawer-section-label">{word(lang,'الإحصائيات من 0 إلى 10','Stats from 0 to 10')}</div>{STAT_KEYS.map(k=><label className="ux-slider" key={k}><span>{word(lang,...STAT_NAMES[k])}</span><input type="number" min="0" max="10" step="1" value={stats[k]??''} onChange={e=>setStats(s=>({...s,[k]:e.target.value===''?null:Number(e.target.value)}))}/><output>{stats[k]??'—'}</output></label>)}<SubmitRow busy={busy} lang={lang} submitLabel={edit?word(lang,'حفظ التعديلات','Save changes'):word(lang,'حفظ شخصية اللعبة','Save playable character')}/></form>
 </Drawer>}
 </section>
}

function ToolDiagramGate({lang,onCreate}){const [busy,setBusy]=useState(false),[error,setError]=useState('');return <section className="spark-panel"><h2>{tr(lang,'toolDiagramMissing')}</h2>{error&&<p role="alert">{error}</p>}<button className="btn btn-primary" disabled={busy} onClick={async()=>{setBusy(true);try{await onCreate()}catch(e){setError(e.message)}finally{setBusy(false)}}}>{tr(lang,'createToolDiagram')}</button></section>}
